root_custody_check.cmd:
$ErrorActionPreference='Stop'
$rp4Root='private-input/0ec5f26c567f416b9513'
$rp4Evidence=Get-Content -LiteralPath "$rp4Root/artifacts/rp4_v3_secondary_closeout/evidence.json" -Raw | ConvertFrom-Json -AsHashtable
$rp4Receipt=Get-Content -LiteralPath "$rp4Root/artifacts/rp4_v3_secondary_closeout/receipt.json" -Raw | ConvertFrom-Json -AsHashtable
$rp4InputCount=0
foreach($rp4Pair in $rp4Evidence.input_sha256.GetEnumerator()) { if ((Get-FileHash -Algorithm SHA256 -LiteralPath $rp4Pair.Key).Hash.ToLowerInvariant() -ne $rp4Pair.Value) {throw 'FINAL_INPUT_HASH_DRIFT'}; $rp4InputCount++ }
foreach($rp4Pair in $rp4Receipt.artifacts_sha256.GetEnumerator()) { if ((Get-FileHash -Algorithm SHA256 -LiteralPath $rp4Pair.Key).Hash.ToLowerInvariant() -ne $rp4Pair.Value) {throw 'FINAL_OUTPUT_HASH_DRIFT'} }
$rp4Header='| Ventana | Familia | Contraste | Delta | IC95% | Reducción % | p unilateral nominal | Decisión | N sesiones/orígenes |'
$rp4Pattern='(?m)^'+[regex]::Escape($rp4Header)+'\r?\n(?:\|[^\r\n]*(?:\r?\n|$)){9}'
$rp4BlockHashes=@{}
foreach($rp4Name in @('results_v3_revision1.md','results_v3_revision2.md')) {
$rp4Bytes=[System.IO.File]::ReadAllBytes("$rp4Root/docs/rp4/$rp4Name")
$rp4Text=[System.Text.Encoding]::UTF8.GetString($rp4Bytes)
$rp4Matches=[regex]::Matches($rp4Text,$rp4Pattern)
if($rp4Matches.Count -ne 1) {throw 'PRIMARY_TABLE_NOT_UNIQUE'}
$rp4BlockBytes=[System.Text.Encoding]::UTF8.GetBytes($rp4Matches[0].Value)
$rp4BlockHash=[System.Convert]::ToHexString([System.Security.Cryptography.SHA256]::HashData($rp4BlockBytes)).ToLowerInvariant()
if($rp4BlockHash -ne '3812b6a1a881c1ed06dc17f84fc47971d44452c19b4d21a0e3ca4c8af7f0e921') {throw 'PRIMARY_TABLE_BYTE_DRIFT'}
$rp4BlockHashes[$rp4Name]=$rp4BlockHash
}
$rp4Frozen=@{'docs/rp4/results_v4.md'='c42316748a57cfc1ce73681a98bacb1fb157ee3ec13983e222e3494d1996a2c7';'artifacts/rp4_v4_b4/report_manifest.json'='a387b789158b78232b29911ae63638a0367ae3acb5a21e5672dbcfaec4cba56f';'docs/rp4/results_v3.md'='86703434ae2d1d8e2ef3a9c59ae9737f3a4e4c8460234076b794e04ac2deee1f';'docs/rp4/results_v3_revision1.md'='f209a54519298d8ee7308a8dc20b5c293d0da4fbad807709aed8aca2feb1db03'}
foreach($rp4Pair in $rp4Frozen.GetEnumerator()) {if((Get-FileHash -Algorithm SHA256 -LiteralPath "$rp4Root/$($rp4Pair.Key)").Hash.ToLowerInvariant() -ne $rp4Pair.Value){throw 'FROZEN_REPORT_DRIFT'}}
if($rp4Receipt.exit_code -ne 0 -or $rp4Receipt.status -ne 'COMPLETE' -or $rp4Evidence.mz_status -ne 'NO_VERIFICABLE_NO_ARITHMETICAL_BUG_DEMONSTRATED' -or $rp4Evidence.prior_primary_changed -or $rp4Evidence.v4_changed) {throw 'FINAL_STATUS_INVALID'}
[pscustomobject]@{status='PASS';input_hashes_verified=$rp4InputCount;output_hashes_verified=$rp4Receipt.artifacts_sha256.Count;primary_table_byte_hashes=$rp4BlockHashes;unchanged_frozen_reports=$rp4Frozen;mz_status=$rp4Evidence.mz_status;model_refits_by_report=$rp4Receipt.model_fits;new_inference_calculations_by_report=$rp4Receipt.new_inference_calculations;receipt_sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath "$rp4Root/artifacts/rp4_v3_secondary_closeout/receipt.json").Hash.ToLowerInvariant()} | ConvertTo-Json -Depth 6

qa_check.cmd:
$ErrorActionPreference='Stop'
$rp4QaRoot='private-input/6b4b036daf2cde056f1c'
$rp4Repo='private-input/0ec5f26c567f416b9513'
foreach($rp4Name in @('qa_receipt.json','qa_newton_execution_receipt.json')) {
$rp4Qa=Get-Content -LiteralPath "$rp4QaRoot/$rp4Name" -Raw | ConvertFrom-Json -AsHashtable
$rp4Count=0
foreach($rp4Pair in $rp4Qa.source_sha256.GetEnumerator()) { if ((Get-FileHash -Algorithm SHA256 -LiteralPath "$rp4Repo/$($rp4Pair.Key)").Hash.ToLowerInvariant() -ne $rp4Pair.Value) { throw 'QA_SOURCE_HASH_DRIFT' }; $rp4Count++ }
[pscustomobject]@{file=$rp4Name;source_hashes_checked=$rp4Count;numeric_threads_max=$rp4Qa.numeric_threads_max;numeric_process_priority=$rp4Qa.numeric_process_priority;junit=$rp4Qa.junit;command_payload_keys=@($rp4Qa.commands[0].Keys);environment=$rp4Qa.environment} | ConvertTo-Json -Depth 8
}
foreach($rp4XmlName in @('qa_newton.junit.xml','qa_report_newton_execution.junit.xml')) {
[xml]$rp4Xml=Get-Content -LiteralPath "$rp4QaRoot/$rp4XmlName" -Raw
$rp4Suite=$rp4Xml.testsuites.testsuite
if([int]$rp4Suite.failures -ne 0 -or [int]$rp4Suite.errors -ne 0 -or [int]$rp4Suite.skipped -ne 0) {throw 'QA_JUNIT_FAILED_OR_SKIPPED'}
[pscustomobject]@{junit=$rp4XmlName;sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath "$rp4QaRoot/$rp4XmlName").Hash.ToLowerInvariant();tests=$rp4Suite.tests;failures=$rp4Suite.failures;errors=$rp4Suite.errors;skipped=$rp4Suite.skipped;timestamp=$rp4Suite.timestamp;seconds=$rp4Suite.time} | ConvertTo-Json -Compress
}
